using System.IO;
using System.Reflection;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
[InitializeOnLoad]
public static class MeasurementResumeDiagnostics063
{
    const string Key = "CH.Measurement050.Smoke";
    static MeasurementResumeDiagnostics063()
    {
        Debug.Log("[ScenePath063 harness] Reload callback: pending=" + SessionState.GetBool(Key, false));
        EditorApplication.update += ResumePending;
    }
    public static void Run()
    {
        EditorSceneManager.OpenScene("Assets/Measurement050/A.unity");
        SessionState.SetString(Key + ".state", File.ReadAllText("Artifacts/pre-reload.json"));
        SessionState.SetBool(Key, true);
        Debug.Log("[ScenePath063 harness] Request real script reload of saved measurement fixture state.");
        EditorUtility.RequestScriptReload();
    }
    static void ResumePending()
    {
        if (!SessionState.GetBool(Key, false)) return;
        EditorApplication.update -= ResumePending;
        if (EditorApplication.isCompiling) { EditorApplication.update += ResumePending; return; }
        Debug.Log("[ScenePath063 harness] Resume original measurement assertions.");
        typeof(UnityMeasurementSmoke).GetMethod("Resume", BindingFlags.NonPublic | BindingFlags.Static).Invoke(null, null);
    }
}

using System.Reflection;
using UnityEditor;
using UnityEngine;
[InitializeOnLoad]
public static class MeasurementResumeScheduling063
{
    const string Key = "CH.Measurement050.Smoke";
    static MeasurementResumeScheduling063()
    {
        Debug.Log("[ScenePath063 harness] Reload scheduling: pending=" + SessionState.GetBool(Key, false));
        if (SessionState.GetBool(Key, false)) EditorApplication.update += ResumePending;
    }
    static void ResumePending()
    {
        if (EditorApplication.isCompiling) return;
        EditorApplication.update -= ResumePending;
        if (!SessionState.GetBool(Key, false)) return;
        Debug.Log("[ScenePath063 harness] Resume original measurement assertions after script reload.");
        typeof(UnityMeasurementSmoke).GetMethod("Resume", BindingFlags.NonPublic | BindingFlags.Static).Invoke(null, null);
    }
}
